// Cloudflare Worker entry: re-exports the OpenNext fetch handler and adds a
// scheduled() handler for the two cron triggers. OpenNext only generates a
// fetch handler, so the crons live here and call the app's own cron routes.
import { log } from "./src/lib/log";
// @ts-expect-error - generated by `opennextjs-cloudflare build`
import worker from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

export default {
  fetch(request: Request, env: Env, ctx: ExecutionContext) {
    return worker.fetch(request, env, ctx);
  },

  async scheduled(event: ScheduledEvent, env: Env, ctx: ExecutionContext) {
    const path = event.cron === "30 3 * * MON" ? "/api/digest" : "/api/reminders";
    const req = new Request(`https://cron.internal${path}`, {
      headers: { Authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      (worker.fetch(req, env, ctx) as Promise<Response>)
        .then(async (res) => {
          if (!res.ok) {
            const body = await res.text().catch(() => "");
            log.error(`cron ${event.cron} -> ${path} failed: HTTP ${res.status} ${body.slice(0, 300)}`);
          }
        })
        .catch((e: unknown) => log.error(`cron ${event.cron} -> ${path} threw:`, e))
    );
  },
};
